// Estimated annual peaks expressed as solar longitude (IMO visual shower calendar).
const METEORS = [
  ['Quadrantids', 283.25, 120], ['Lyrids', 32.32, 18], ['Eta Aquariids', 45.5, 50],
  ['Perseids', 140, 100], ['Orionids', 208, 20], ['Leonids', 235.27, 15],
  ['Geminids', 262.2, 150], ['Ursids', 270.7, 10],
];
const SEASONS = ['March equinox', 'June solstice', 'September equinox', 'December solstice'];

function solarLongitude(time) {
  const centuries = days(time) / 36525;
  const mean = 280.46646 + centuries * (36000.76983 + .0003032 * centuries);
  const anomaly = R * (357.52911 + centuries * (35999.05029 - .0001537 * centuries));
  const centre = Math.sin(anomaly) * (1.914602 - .004817 * centuries)
    + .019993 * Math.sin(2 * anomaly) + .000289 * Math.sin(3 * anomaly);
  return mean + centre - .00569 - .00478 * Math.sin(R * (125.04 - 1934.136 * centuries));
}

function nextSolarLongitude(now, longitude) {
  const advance = ((longitude - solarLongitude(now)) % 360 + 360) % 360;
  const target = solarLongitude(now) + advance;
  let lo = now;
  let hi = now + 370 * DAY;
  while (hi - lo > 60000) {
    const middle = (lo + hi) / 2;
    if (solarLongitude(middle) < target) lo = middle;
    else hi = middle;
  }
  return hi;
}

function upcomingMoonPhases(now) {
  const events = [];
  const start = Math.floor(now / 36e5) * 36e5;
  let previous = illum(start).phase;
  for (let i = 1; i <= 24 * 31 && events.length < 4; i++) {
    const time = start + i * 36e5;
    const phase = illum(time).phase;
    for (let quarter = 0; quarter < 4; quarter++) {
      const before = (previous - quarter / 4 + 1.5) % 1 - .5;
      const after = (phase - quarter / 4 + 1.5) % 1 - .5;
      if (before < 0 && after >= 0 && after - before < .2) {
        const crossing = time - 36e5 + 36e5 * before / (before - after);
        if (crossing > now) events.push({t: crossing, q: quarter});
      }
    }
    previous = phase;
  }
  return events;
}

function panelHeading(label, title, width, reading = '') {
  return `<p class="lab"><span class="plain-title">${label}</span><svg class="rail-title" role="img" aria-label="${title}" viewBox="0 0 ${width} 32"><text x="0" y="29" font-size="38" textLength="${width}" lengthAdjust="spacingAndGlyphs">${title}</text></svg><span class="rail-tail" aria-hidden="true">${reading}</span></p>`;
}

